facilityFormItem.valueChangedEventHandler:
        var employeeId = formItem.value;
        // Очистить поля отпусков.
        functions.setValue('VacationId', null);
        functions.removeError(context.errorInitiator);

          context.checkEmployeeConsentSigned({ functions, context, employeeId });

          ESS.network.sendRequest(`/api/functions/PartTimeHasPerformingVacations?employeeId=${employeeId}&isSelfRecall=false`)
          .then(function (info) {
            if (info) {
              ESS.toasts.showToast(info, ESS.enums.ToastType.ERROR, false);
            }
          });
          if (!functions.getValues().RecallDate)
          {
            var tomorrow = new Date();
            tomorrow.setDate(tomorrow.getDate() + 1);
            functions.setValue('RecallDate', tomorrow);
          }
          context.changeVacation();
        }

var initiatorId = functions.getValues().Employee;
var recallDate = formItem.value;
if (recallDate && initiatorId) {
  var options = { dateStyle: "long" };
  var recallDateFromControl = new Date(recallDate).toLocaleString('ru-RU', options);
  var recallDateFormated = new Date(recallDate).toLocaleDateString('ru-RU');
  functions.setValue('Field_Дата выхода на работу', recallDateFromControl);
  functions.setValue('recallDateFormated', recallDateFormated);
}
context.changeVacation();

var vacationId = formItem.value;
if (vacationId) {
  ESS.network.sendRequest(`/api/functions/GetVacationPeriodInfo?vacationId=${vacationId}`)
  .then(function (vacationInfo) {
    functions.setValue('VacationPeriod', vacationInfo);
  });
  var recallDate = functions.getValues().RecallDate;
  var Compensation = functions.getValues().Compensation;
  var rows = functions.getValues().NewVacationDateGrid;
  var vacationKindIdsArray = [];
  var beginDateArray = [];
  var vacationDurationArray = [];
  var endDateArray = [];
  rows.forEach(row => {
    if (row.rowValues.BeginDate && row.rowValues.VacationDuration) {
      vacationKindIdsArray.push(row.rowValues.VacationKindId);
      var beginDate = `"${row.rowValues.BeginDate}"`;
      beginDateArray.push(beginDate);
      vacationDurationArray.push(row.rowValues.VacationDuration);
      var endDate = `"${row.rowValues.EndDate}"`;
      endDateArray.push(endDate);
    };
  });
  if (vacationId){
    ESS.scripts.HRProVacations.printHintReschedulingDates({ field: 'DaysLeftToTransfer', functions, recallDate, vacationId, vacationKindIdsArray, vacationDurationArray, Compensation });
  }
} else {
  functions.setValue('VacationPeriod', null);
  functions.setValue('DaysLeftToTransfer', null);
}

facilityFormItem.itemAddingEventHandler:
var vacationId = functions.getValues().VacationId;
if (vacationId) {
  ESS.network.sendRequest(`/api/functions/GetVacationKindIdFromVacationId?vacationId=${vacationId}`)
  .then(function (vacationKindId) {
    var rowindex = functions.getValues().NewVacationDateGrid.length - 1;
    var itemIndex = functions.getValues()['NewVacationDateGrid'][rowindex].rowIndex;
    functions.setValue('NewVacationDateGrid', vacationKindId, itemIndex, 'VacationKindId');
  })
  .catch(error => {
    ESS.toasts.showToast(error.message, ESS.enums.ToastType.ERROR, false);
  });
}
resolve();

facilityFormItem.itemRemovedEventHandler:
          var recallDate = functions.getValues().RecallDate;
          var vacationId = functions.getValues().VacationId;
          var Compensation = functions.getValues().Compensation;
          var rows = functions.getValues().NewVacationDateGrid;
          var vacationKindIdsArray = [];
          var beginDateArray = [];
          var vacationDurationArray = [];
          var endDateArray = [];
          var VacationsData = '';
          rows.forEach(row => {
            if (row.rowValues.BeginDate && row.rowValues.VacationDuration) {
              vacationKindIdsArray.push(row.rowValues.VacationKindId);
              var beginDate = `"${row.rowValues.BeginDate}"`;
              beginDateArray.push(beginDate);
              vacationDurationArray.push(row.rowValues.VacationDuration);
              var endDate = `"${row.rowValues.EndDate}"`;
              endDateArray.push(endDate);
              VacationsData += row.rowValues.VacationKindId + '~' + row.rowValues.BeginDate + '~' + row.rowValues.EndDate +'!';
            };
          });
          functions.setValue('VacationsData', VacationsData);

          if (vacationId) {
            var urlIsCompensationEnable = `/api/functions/IsCompensationEnable?recallDate=${recallDate}&vacationId=${vacationId}&durations=[${vacationDurationArray}]`;
            ESS.network.sendRequest(urlIsCompensationEnable).then(function (isCompEnable){
              functions.setIsItemDisabled('Compensation', !isCompEnable);
            });

            ESS.scripts.HRProVacations.printHintReschedulingDates({ field: 'DaysLeftToTransfer', functions, recallDate, vacationId, vacationKindIdsArray, vacationDurationArray, Compensation });
            
            ESS.scripts.HRProVacations.printErrorReschedulingDates({ functions, recallDate, vacationId, vacationKindIdsArray, vacationDurationArray, Compensation });

            var urlTemplate = `/api/functions/CheckExecutionShiftVacations?vacationIds=[${vacationId}]`;
            ESS.network.sendRequest(urlTemplate).then(function (errors){
              if(errors.length > 0) {
                functions.removeError(context.errorExecutionShift);
                context.errorExecutionShift = functions.showError(errors);
              } else {
                functions.removeError(context.errorExecutionShift);
              }
            });
          }

column.valueChangedEventHandler:
var today = new Date();
var yesterday = new Date(today);
yesterday.setDate(today.getDate() -1);
var beginDateValue = formItem.value;
var dateFromControl = new Date(beginDateValue).getTime();
functions.removeError(context.errorDate);
if (dateFromControl < yesterday.getTime()) {
  context.errorDate = functions.showError(ESS.L('@HRPROVACATIONS.ERROR_DATE_BEGIN'));
}
var initiatorId = functions.getValues().Employee;
var durationValue = functions.getValues().NewVacationDateGrid.find(function (x) {
  return x.rowIndex === formItem.index;
}).rowValues['VacationDuration'];
var vacationKindId = functions.getValues().NewVacationDateGrid.find(function (x) {
  return x.rowIndex === formItem.index;
}).rowValues['VacationKindId'];

if (durationValue && beginDateValue) {
  var url = `/api/functions/GetVacationEndDate?dateBegin=${beginDateValue}&duration=${durationValue}&userId=${initiatorId}&vacationKindId=${vacationKindId}`;
  ESS.network.sendRequest(url)
  .then(function (newEndDateValue) {
    functions.setValue('NewVacationDateGrid', newEndDateValue, formItem.index, 'EndDate');
  });
};

              var initiatorId = functions.getValues().Employee;
              var beginDateValue = functions.getValues().NewVacationDateGrid.find(function (x) {
                return x.rowIndex === formItem.index;
              }).rowValues['BeginDate'];
              var durationValue = functions.getValues().NewVacationDateGrid.find(function (x) {
                return x.rowIndex === formItem.index;
              }).rowValues['VacationDuration'];
              var vacationKindId = functions.getValues().NewVacationDateGrid.find(function (x) {
                return x.rowIndex === formItem.index;
              }).rowValues['VacationKindId'];
              
              if (durationValue <= 0) {
                functions.removeError(context.errorId);
                context.errorId = functions.showError(ESS.L('@HRPROVACATIONS.ERROR_DURATION'));
              } else {
                functions.removeError(context.errorId);
              }

              if (durationValue && beginDateValue) {
                var endDate = functions.getValues().NewVacationDateGrid.find(function (x) {
                  return x.rowIndex === formItem.index;
                }).rowValues['EndDate'];
                var url = `/api/functions/GetVacationEndDate?dateBegin=${beginDateValue}&duration=${durationValue}&userId=${initiatorId}&vacationKindId=${vacationKindId}`;
                ESS.network.sendRequest(url)
                .then(function (newEndDateValue) {
                  if (new Date(newEndDateValue).getTime() != new Date(endDate).getTime()) {
                    functions.setValue('NewVacationDateGrid', newEndDateValue, formItem.index, 'EndDate');
                  }
                });
              };

              var initiatorId = functions.getValues().Employee;
              var beginDate = functions.getValues().NewVacationDateGrid.find(function (x) {
                return x.rowIndex === formItem.index;
              }).rowValues['BeginDate'];
              var endDate = functions.getValues().NewVacationDateGrid.find(function (x) {
                return x.rowIndex === formItem.index;
              }).rowValues['EndDate'];
              var vacationKindId = functions.getValues().NewVacationDateGrid.find(function (x) {
                return x.rowIndex === formItem.index;
              }).rowValues['VacationKindId'];
              functions.removeError(context.errorEndDate);
              if (beginDate && endDate && vacationKindId) {
                var checkUrl = `/api/functions/CheckVacationHasHoliday?periodBegin=${beginDate}&periodEnd=${endDate}&employeeId=${initiatorId}&vacationKindId=${vacationKindId}`;
                ESS.network.sendRequest(checkUrl)
                .then(function (warning) {
                  if(warning.length > 0)
                    ESS.toasts.showToast(warning, ESS.enums.ToastType.ERROR, true);
                });

                var url = `/api/functions/DurationInCalendarDaysWithoutHoliday?startDate=${beginDate}&endDate=${endDate}&userId=${initiatorId}&vacationKindId=${vacationKindId}`
                ESS.network.sendRequest(url)
                .then(function (newDuration) {
                  if (newDuration <= 0) {
                    context.errorEndDate = functions.showError(ESS.L('@HRPROVACATIONS.ERROR_DATE_END'));
                  }
                  else {
                    var needCheckRequiredDuration = functions.getValues().IgnoreRequiredDuration;
                    var recallDate = functions.getValues().RecallDate;
                    var vacationId = JSON.parse(functions.getValues()['VacationId']);
                    var Compensation = functions.getValues().Compensation;
                    var rows = functions.getValues().NewVacationDateGrid;
                    var vacationKindIdsArray = [];
                    var beginDateArray = [];
                    var vacationDurationArray = [];
                    var endDateArray = [];
                    var VacationsData = '';
                    rows.forEach(row => {
                      if (row.rowValues.BeginDate && row.rowValues.VacationDuration) {
                        vacationKindIdsArray.push(row.rowValues.VacationKindId);
                        var beginDate = `"${row.rowValues.BeginDate}"`;
                        beginDateArray.push(beginDate);
                        vacationDurationArray.push(row.rowValues.VacationDuration);
                        var endDate = `"${row.rowValues.EndDate}"`;
                        endDateArray.push(endDate);
                        VacationsData += row.rowValues.VacationKindId + '~' + row.rowValues.BeginDate + '~' + row.rowValues.EndDate +'!';
                      };
                    });
                    functions.setValue('VacationsData', VacationsData);

                    var urlIsCompensationEnable = `/api/functions/IsCompensationEnable?recallDate=${recallDate}&vacationId=${vacationId}&durations=[${vacationDurationArray}]`;
                    ESS.network.sendRequest(urlIsCompensationEnable).then(function (isCompEnable){
                      functions.setIsItemDisabled('Compensation', !isCompEnable);
                      if (!isCompEnable)
                        functions.setValue('Compensation', false);
                    });

                    ESS.scripts.HRProVacations.printHintReschedulingDates({ field: 'DaysLeftToTransfer', functions, recallDate, vacationId, vacationKindIdsArray, vacationDurationArray, Compensation });
                    
                    var urlTemplate = `/api/functions/CheckAllVacationShiftDates?vacationIds=[${vacationId}]&vacationKindIds=[${vacationKindIdsArray}]&beginDates=[${beginDateArray}]&durations=[${vacationDurationArray}]&endDates=[${endDateArray}]`;
                    ESS.network.sendRequest(urlTemplate).then(function (errors){
                      if(errors.length > 0) {
                        functions.removeError(context.errorVacations);
                        context.errorVacations = functions.showError(errors);
                      } else {
                        functions.removeError(context.errorVacations);
                      }
                    });
                    if (vacationKindIdsArray.length > 0) {
                      ESS.scripts.HRProVacations.printErrorReschedulingDates({ functions, recallDate, vacationId, vacationKindIdsArray, vacationDurationArray, Compensation });
                    };
                    var urlTemplate = `/api/functions/CheckExecutionShiftVacations?vacationIds=[${vacationId}]`;
                    ESS.network.sendRequest(urlTemplate).then(function (errors){
                      if(errors.length > 0) {
                        functions.removeError(context.errorExecutionShift);
                        context.errorExecutionShift = functions.showError(errors);
                      } else {
                        functions.removeError(context.errorExecutionShift);
                      }
                    });
                    
                    if (!needCheckRequiredDuration) {
                      var urlCheckEmployeeVacationsDurations = `/api/functions/CheckEmployeeVacationsDurations?vacationId=${vacationId}&employeeId=${initiatorId}&recallDate=${recallDate}`;
                      ESS.network.sendRequest(urlCheckEmployeeVacationsDurations).then(function (hasRequiredDuration){
                        if (hasRequiredDuration == false) {
                          var urlIsRequiredDurationBroken = `/api/functions/CheckVacationRequiredDuration?vacationIds=[${vacationId}]&vacationKindIds=[${vacationKindIdsArray}]&beginDates=[${beginDateArray}]&durations=[${vacationDurationArray}]&endDates=[${endDateArray}]`;
                          ESS.network.sendRequest(urlIsRequiredDurationBroken).then(function (isIgnoreDurationEnable){
                            functions.removeError(context.errorRequiredDuration);
                            if (isIgnoreDurationEnable){
                              context.errorRequiredDuration = functions.showError(isIgnoreDurationEnable + ' ' + ESS.L('@HRPROVACATIONS.FACILITIES_RECALLVACATIONEMPLOYEE_NEEDCONTROLDURATION_HINT'));
                            }
                          });                    
                        }
                      });
                    }
                  }
                });
              }

facilityFormItem.valueChangedEventHandler:
          var recallDate = functions.getValues().RecallDate;
          var vacationId = JSON.parse(functions.getValues()['VacationId']);
          var Compensation = formItem.value;
          functions.setIsItemDisabled('NewVacationDateGrid', Compensation, 'BeginDate');
          functions.setIsItemDisabled('NewVacationDateGrid', Compensation, 'VacationDuration');
          var rows = functions.getValues().NewVacationDateGrid;
          var vacationKindIdsArray = [];
          var vacationDurationArray = [];
          rows.forEach(row => {
            if (row.rowValues.BeginDate && row.rowValues.VacationDuration) {
              vacationKindIdsArray.push(row.rowValues.VacationKindId);
              vacationDurationArray.push(row.rowValues.VacationDuration);
            };
          });

          if (vacationId){
            ESS.scripts.HRProVacations.printHintReschedulingDates({ field: 'DaysLeftToTransfer', functions, recallDate, vacationId, vacationKindIdsArray, vacationDurationArray, Compensation });
          }

          if (vacationKindIdsArray.length > 0) {
            ESS.scripts.HRProVacations.printErrorReschedulingDates({ functions, recallDate, vacationId, vacationKindIdsArray, vacationDurationArray, Compensation });
          };

var needCheckRequiredDuration = formItem.value;
if (needCheckRequiredDuration) {
  functions.removeError(context.errorRequiredDuration);
}
else {
  var initiatorId = functions.getValues().Employee;
  var vacationId = JSON.parse(functions.getValues()['VacationId']);
  var recallDate = functions.getValues().RecallDate;
  var rows = functions.getValues().NewVacationDateGrid;
  var vacationKindIdsArray = [];
  var beginDateArray = [];
  var vacationDurationArray = [];
  var endDateArray = [];
  rows.forEach(row => {
    if (row.rowValues.BeginDate && row.rowValues.VacationDuration) {
      vacationKindIdsArray.push(row.rowValues.VacationKindId);
      var beginDate = `"${row.rowValues.BeginDate}"`;
      beginDateArray.push(beginDate);
      vacationDurationArray.push(row.rowValues.VacationDuration);
      var endDate = `"${row.rowValues.EndDate}"`;
      endDateArray.push(endDate);
    };
  });
  if (!needCheckRequiredDuration) {
    var urlCheckEmployeeVacationsDurations = `/api/functions/CheckEmployeeVacationsDurations?vacationId=${vacationId}&employeeId=${initiatorId}&recallDate=${recallDate}`;
    ESS.network.sendRequest(urlCheckEmployeeVacationsDurations).then(function (hasRequiredDuration){
      if (!hasRequiredDuration) {
        var urlIsRequiredDurationBroken = `/api/functions/CheckVacationRequiredDuration?vacationIds=[${vacationId}]&vacationKindIds=[${vacationKindIdsArray}]&beginDates=[${beginDateArray}]&durations=[${vacationDurationArray}]&endDates=[${endDateArray}]`;
        ESS.network.sendRequest(urlIsRequiredDurationBroken).then(function (isIgnoreDurationEnable){
          functions.removeError(context.errorRequiredDuration);
          if (isIgnoreDurationEnable){
            context.errorRequiredDuration = functions.showError(isIgnoreDurationEnable + ' ' + ESS.L('@HRPROVACATIONS.FACILITIES_RECALLVACATIONEMPLOYEE_NEEDCONTROLDURATION_HINT'));
          }
        });
      }
    });
  }
}

facility.openingEventHandler:
      const initiatorId = functions.getValues().Initiator;
      context.checkEmployeeConsentSigned = ESS.scripts.HRProVacations.checkEmployeeConsentSigned;
      functions.setValue('IgnoreRequiredDuration', false);
      ESS.network.sendRequest(`/api/functions/CheckPersonAllEmployeesConsentSigned`)
      .then(function (isConsentSigned) {
          ESS.network.sendRequest(`/api/functions/GetVacationRecallStatementTemplateId?employeeId=${initiatorId}&isShiftVacation=false&isVacationRecall=true&isAuthorManager=true`)
          .then(function (VacationStatementData) {
            if (VacationStatementData.Error.length == 0) {

              var templateId = JSON.parse(VacationStatementData.TemplateId);
              var docKindId = JSON.parse(VacationStatementData.DocumentKindId);
              functions.setValue('TemplateId', templateId);
              functions.setValue('DocumentKindId', docKindId);
              functions.setValue('IsFromEssAccount', true);
              functions.setValue('Initiator', initiatorId);
              resolve();
            } else {
              ESS.dialogs.showMessageBox(ESS.L('@HRPROVACATIONS.ERROR_COMMON'), VacationStatementData.Error);
            }
          })
          .catch(function (error) {
            ESS.toasts.showToast(error.message, ESS.enums.ToastType.ERROR, false);
          });
          
        })
      .catch(function (error) {
        ESS.toasts.showToast(error.message, ESS.enums.ToastType.ERROR, false);
      });
      
      context.changeVacation = function(){
        var employeeId = functions.getValues().Employee;
        var recallDate = functions.getValues().RecallDate;
        var vacationId = functions.getValues().VacationId;
        if (employeeId && recallDate){
          var urlGetRecallVacation = `/api/functions/GetRecallVacations?employeeId=${employeeId}&recallDate=${recallDate}`;
          ESS.network.sendRequest(urlGetRecallVacation)
          .then(function (vacation){
            if (vacation.id) {
              var urlTemplate = `/api/functions/CheckExecutionShiftVacations?vacationIds=[${vacation.id}]`;
              ESS.network.sendRequest(urlTemplate).then(function (errors){
                if (errors.length > 0) {
                  functions.removeError(context.errorExecutionShift);
                  context.errorExecutionShift = functions.showError(errors);
                } else {
                  functions.removeError(context.errorExecutionShift);
                }
              });
            } else {
              functions.setValue('DaysLeftToTransfer', null);
            }

            var dateStart = new Date(vacation.dateStart);
            var dateEnd = new Date(vacation.dateEnd);
            var dateRecall = new Date(recallDate);
            dateStart.setHours(0, 0, 0, 0);
            dateEnd.setHours(0, 0, 0, 0);
            dateRecall.setHours(0, 0, 0, 0);

            if (dateRecall >= dateStart && dateRecall <= dateEnd){
              var rows = functions.getValues().NewVacationDateGrid;
              var vacationKindIdsArray = [];
              var vacationDurationArray = [];
              var Compensation = functions.getValues().Compensation;
              rows.forEach(row => {
                if (row.rowValues.VacationDuration) {
                  vacationKindIdsArray.push(row.rowValues.VacationKindId);
                  vacationDurationArray.push(row.rowValues.VacationDuration);
                };
              });
              ESS.scripts.HRProVacations.printHintReschedulingDates({ field: 'DaysLeftToTransfer', functions, recallDate, vacationId: vacation.id, vacationKindIdsArray, vacationDurationArray, Compensation });
              ESS.scripts.HRProVacations.printErrorReschedulingDates({ functions, recallDate, vacationId: vacation.id, vacationKindIdsArray, vacationDurationArray, Compensation });
            }
            
            var isVacation = vacation.id > 0;
            functions.setIsItemDisabled('NewVacationDateGrid', !isVacation, 'BeginDate');
            functions.setIsItemDisabled('NewVacationDateGrid', !isVacation, 'VacationDuration');
            if (isVacation) {
              if (vacation.id != vacationId) {
                var rows = functions.getValues().NewVacationDateGrid;
                rows.forEach(row => {
                  functions.removeItem('NewVacationDateGrid', row.rowIndex);
                });
                functions.setValue('VacationId', vacation.id);
                ESS.network.sendRequest(`/api/functions/IsCompensationVisible?vacationId=${vacation.id}`)
                .then(function (isCompVisible){
                  functions.setIsItemHidden('Compensation', !isCompVisible);
                });
                var urlIsIgnoreRequiredDurationVisible = `/api/functions/IsIgnoreRequiredDurationVisible?vacationId=${vacation.id}&employeeId=${employeeId}&recallDate=${recallDate}`;
                ESS.network.sendRequest(urlIsIgnoreRequiredDurationVisible)
                .then(function (isIgnoreDurationVisible){
                  functions.setIsItemHidden('IgnoreRequiredDuration', !isIgnoreDurationVisible);
                });
              }
            }
            else if (vacationId) {
              functions.setValue('VacationId', null);
              functions.setIsItemHidden('Compensation', true);
              functions.setValue('Compensation', false);
              functions.setIsItemHidden('IgnoreRequiredDuration', true);
              var rows = functions.getValues().NewVacationDateGrid;
              rows.forEach(row => {
                functions.removeItem('NewVacationDateGrid', row.rowIndex);
              });
            }
          })
          .catch(function (error) {
            ESS.toasts.showToast(error.message, ESS.enums.ToastType.ERROR, false);
          });
        }
      }
